33	// true/false or 1/0 so the test binds to the MEANING; everything else is matched exactly.
34	const toggledRecord = (id: number, done: boolean) =>
35	  new RegExp(`^TASK_TOGGLED id=${id} done=${done ? '(?:true|1)' : '(?:false|0)'}$`);
